// C program for the function called BucketSortN
// Contains target function implementation and dependency signatures

#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Node
{
    int data;
    struct Node *next;
};

// Forward declarations for dependency functions
void freeList(struct Node *list);
struct Node *InsertionSort(struct Node *list);
int getBucketIndexSafe(int value, int interval, int nbucket);

// Target function implementation
void BucketSortN(int arr[], int n, int nbucket, int interval)
{
    int i, j;
    struct Node **buckets;

    if (arr == NULL || n <= 0 || nbucket <= 0 || interval <= 0)
    {
        return;
    }

    /* allocate memory for array of pointers to the buckets */
    buckets = (struct Node **)malloc(sizeof(struct Node *) * nbucket);
    if (buckets == NULL)
    {
        return;
    }

    /* initialize pointers to the buckets */
    for (i = 0; i < nbucket; ++i)
    {
        buckets[i] = NULL;
    }

    /* put items into the buckets */
    /* creates a link list in each bucket slot */
    for (i = 0; i < n; ++i)
    {
        struct Node *current;
        int pos = getBucketIndexSafe(arr[i], interval, nbucket);
        current = (struct Node *)malloc(sizeof(struct Node));
        if (current == NULL)
        {
            /* cleanup on allocation failure */
            for (j = 0; j < nbucket; ++j)
            {
                freeList(buckets[j]);
            }
            free(buckets);
            return;
        }
        current->data = arr[i];
        current->next = buckets[pos];
        buckets[pos] = current;
    }

    /* sorting bucket using Insertion Sort */
    for (i = 0; i < nbucket; ++i)
    {
        buckets[i] = InsertionSort(buckets[i]);
    }

    /* put items back to original array */
    for (j = 0, i = 0; i < nbucket; ++i)
    {
        struct Node *node;
        node = buckets[i];
        while (node)
        {
            /* precondition for avoiding out of bounds by the array */
            if (j >= n)
            {
                break;
            }
            arr[j++] = node->data;
            node = node->next;
        }
    }

    /* free memory */
    for (i = 0; i < nbucket; ++i)
    {
        freeList(buckets[i]);
    }
    free(buckets);
}

